import sys,numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot(); o=r.get_obs(depth=True)
for cam, pts in [('egocentric_mirrored_camera',[(519,202),(447,185),(210,165),(240,180),(180,180),(260,180),(220,180)]),('over_shoulder_left_camera',[(760,430),(812,410),(855,438)])]:
 K=np.array(o.meta['cameras'][cam]['intrinsic_cv']); E=np.array(o.meta['cameras'][cam]['extrinsic_cv']); R=E[:,:3]; t=E[:,3]; C=-R.T@t; invK=np.linalg.inv(K); d=o.last_depth[cam]
 print('\n',cam,'origin',np.round(C,3))
 for uv in pts:
  u,v=uv; patch=d[v-3:v+4,u-3:u+4]; vals=patch[patch>0]; ztop=float(np.median(vals)); cp=invK@np.array([u,v,1])*ztop; wp=R.T@(cp-t)
  ray=R.T@(invK@np.array([u,v,1]));
  for zq in ([0.027] if 'egocentric' in cam else [0.027]):
   tau=(zq-C[2])/ray[2]; wq=C+tau*ray
  proj=K@(E@np.r_[wq,1]); proj=proj[:2]/proj[2]
  print(uv,'visible',np.round(wp,3),'at grasp z',np.round(wq,3),'reproj',np.round(proj,1))
# project place world coords at plate plane to egocentric
cam='egocentric_mirrored_camera'; K=np.array(o.meta['cameras'][cam]['intrinsic_cv']); E=np.array(o.meta['cameras'][cam]['extrinsic_cv']);
for xyz in ([.40,-.25,.016],[.45,-.36,.016],[.34,-.32,.016],[.40,-.31,.016]):
 cp=E@np.r_[xyz,1]; pix=K@cp; pix=pix[:2]/pix[2]; print('place',xyz,'pix',np.round(pix,1))
PY

